use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut values = input.split_whitespace();
    let hour: u64 = values.next().unwrap().parse().unwrap();
    let minute: u64 = values.next().unwrap().parse().unwrap();
    let advance: u64 = values.next().unwrap().parse().unwrap();

    let resulting_minutes = (hour * 60 + minute + advance) % (24 * 60);
    println!("{} {}", resulting_minutes / 60, resulting_minutes % 60);
}

