use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();
    let mut values = input.split_whitespace();

    let n: u128 = values.next().unwrap().parse().unwrap();
    let current: u128 = values.next().unwrap().parse().unwrap();
    let steps: u128 = values.next().unwrap().parse().unwrap();

    let zero_based = current - 1;
    let forward = steps % n;
    let distance_to_end = n - zero_based;
    let result = if forward >= distance_to_end {
        forward - distance_to_end
    } else {
        zero_based + forward
    };

    println!("{}", result + 1);
}

