use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin()
        .read_to_string(&mut input)
        .expect("failed to read input");

    let mut numbers = input.split_whitespace();
    let n: usize = numbers
        .next()
        .expect("missing N")
        .parse()
        .expect("invalid N");
    let d: u128 = numbers
        .next()
        .expect("missing D")
        .parse()
        .expect("invalid D");

    let count = numbers
        .take(n)
        .map(|value| value.parse::<u128>().expect("invalid value"))
        .filter(|value| value % d == 0)
        .count();

    println!("{count}");
}

