use std::io::{self, Read};

fn main() {
    let mut input = String::new();
    io::stdin().read_to_string(&mut input).unwrap();

    let mut numbers = input.split_whitespace();
    let weekday: u128 = numbers.next().unwrap().parse().unwrap();
    let days: u128 = numbers.next().unwrap().parse().unwrap();

    println!("{}", (weekday + days) % 7);
}

